package org.skhuconnect.admin.notificationlog.service;
import org.junit.jupiter.api.Test; import org.skhuconnect.admin.notificationlog.entity.*; import org.skhuconnect.admin.notificationlog.repository.NotificationLogRepository; import org.skhuconnect.admin.entity.Admin; import org.springframework.test.util.ReflectionTestUtils; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class AdminNotificationLogServiceTest {@Test void recordsAutomaticAndAdminEventsSeparately(){NotificationLogRepository repository=mock(NotificationLogRepository.class);AdminNotificationLogService service=new AdminNotificationLogService(repository);Admin admin=mock(Admin.class);service.record(NotificationLogType.THRESHOLD_REACHED,null,NotificationLogTargetType.PETITION,10L,"threshold reached");service.record(NotificationLogType.PETITION_RESTORED,admin,NotificationLogTargetType.PETITION,10L,"restored");verify(repository,times(2)).save(any(NotificationLog.class));}}